public class Quarters {

    public static int quarterOf(java.time.LocalDate d) {
        return (d.getMonthValue() - 1) / 3 + 1;
    }

    public static java.time.LocalDate firstDayOfQuarter(java.time.LocalDate d) {
        int firstMonth = (quarterOf(d) - 1) * 3 + 1;
        return java.time.LocalDate.of(d.getYear(), firstMonth, 1);
    }
}
